style.css:
@-moz-document domain("google.com") {
/* Masquer le logo Google d'origine */
    .lnXvI, .k1zDPe, img[alt="Google"] {
        display: none !important;
    }

    /* Insérer votre nom à la place */
    .FPdoLc::before, .lJ9FBc::before, div.logo::before {
        content: "Junior Gnezale";
        font-family: "Product Sans", Arial, sans-serif;
        font-size: 56px;
        font-weight: bold;
        display: block;
        text-align: center;
        margin-bottom: 30px;
        /* Optionnel : couleurs façon Google */
        background: linear-gradient(to right, #4285F4, #EA4335, #FBBC05, #4285F4, #34A853, #EA4335);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }
}
